			numberOfYearDaySchedulesSupportedPerUser: MutableCluster.AsConditional(DoorLock2.YearDayAccessSchedulesComponent.attributes.numberOfYearDaySchedulesSupportedPerUser, { mandatoryIf: [YDSCH] }),
			numberOfHolidaySchedulesSupported: MutableCluster.AsConditional(DoorLock2.HolidaySchedulesComponent.attributes.numberOfHolidaySchedulesSupported, { mandatoryIf: [HDSCH] }),
