			maxRfidCodeLength: MutableCluster.AsConditional(DoorLock2.RfidCredentialComponent.attributes.maxRfidCodeLength, { mandatoryIf: [RID] }),
			minRfidCodeLength: MutableCluster.AsConditional(DoorLock2.RfidCredentialComponent.attributes.minRfidCodeLength, { mandatoryIf: [RID] }),
			credentialRulesSupport: MutableCluster.AsConditional(DoorLock2.UserComponent.attributes.credentialRulesSupport, { mandatoryIf: [USR] }),
